#define PI 3.14159265359

vec3 palette(float t) {
    vec3 a = vec3(0.5, 0.5, 0.5);
    vec3 b = vec3(0.5, 0.5, 0.5);
    vec3 c = vec3(1.0, 1.0, 1.0);
    vec3 d = vec3(0.314, 0.717, 0.184);

    return a + b*cos(6.28318*(c*t*d));
}

mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord * 2. - iResolution.xy) / iResolution.y;
    vec2 uv0 = uv;
    vec3 finalColor = vec3(0.0);

    float time = iTime * 0.3;
    float blur = 0.82;

    for (float i = 0.0; i < 6.0; i++) {
        vec2 pos = uv;
        for (float j = -1.0; j <= 1.0; j += 1.0) {
            for (float k = -1.0; k <= 1.0; k += 1.0) {
                vec2 offset = vec2(j, k) * blur;
                pos = abs((uv + offset) * 1.5 - 0.75) - 0.1;

                float rotOffset = sin(time * 0.1) * 0.3;
                pos *= rot(sin(time + i * 0.1 + rotOffset) * 0.3);

                float d = length(pos) * exp(-length(uv0 + offset));

                vec3 col = palette(length(uv0 + offset) + i * 0.2 + time * 0.2 + sin(pos.x * 5.0 + time));

                d = sin(d * 5.0 + time) / 10.0;
                d = abs(d);
                d = pow(0.01 / d, 1.2);

                finalColor += col * d * (sin(i * 0.5 + time) * 0.5 + 0.5);
            }
        }
    }

    finalColor /= 9.0;

    vec2 glowUV = uv0 * 1.5;
    float glow = 0.1 / (0.1 + length(glowUV));
    finalColor += vec3(glow * sin(time * 0.3), glow * cos(time * 0.4), glow * sin(time * 0.5)) * 0.5;

    float vignette = 1.0 - length(uv0) * 0.4;
    finalColor *= vignette * vignette;

    fragColor = vec4(finalColor, 1.0);
}
